import * as React from "react";
import { type Slot } from "@puckeditor/core";
import "./container.css";

export interface ContainerProps {
  content: Slot;
  tone: "none" | "light" | "white";
  pad: "compact" | "regular" | "spacious";
  maxWidth: "narrow" | "standard" | "wide" | "full";
  align: "left" | "center";
  radius: "none" | "soft" | "round";
}

function SlotPlaceholder() {
  return (
    <div className="p1-container__placeholder">
      Drop blocks here, or add them in the inspector.
    </div>
  );
}

export function ContainerRender({ content, tone, pad, maxWidth, align, radius }: ContainerProps) {
  const Content = content as unknown;
  const hasBackground = tone !== "none";
  const inner =
    typeof Content === "function" ? (
      (() => {
        const Comp = Content as React.ComponentType;
        return <Comp />;
      })()
    ) : (
      <SlotPlaceholder />
    );
  return (
    <div className="p1-container">
      <div className="p1-container__outer">
        <div
          className="p1-container__box"
          data-tone={tone}
          data-pad={hasBackground ? pad : undefined}
          data-radius={hasBackground ? radius : undefined}
        >
          <div className="p1-container__inner" data-maxwidth={maxWidth} data-align={align}>
            {inner}
          </div>
        </div>
      </div>
    </div>
  );
}

import type { ComponentConfig } from "@puckeditor/core";
import { defineMeta } from '../define-meta';
import { ContainerRender, type ContainerProps } from "./container";
export type { ContainerProps };

export const ContainerBlock: ComponentConfig<ContainerProps> = {
  fields: {
    content: { type: "slot" as const },
    tone: {
      type: "select" as const,
      options: [
        { label: "None", value: "none" },
        { label: "Light", value: "light" },
        { label: "White", value: "white" },
      ],
    },
    pad: {
      type: "select" as const,
      options: [
        { label: "Compact", value: "compact" },
        { label: "Regular", value: "regular" },
        { label: "Spacious", value: "spacious" },
      ],
    },
    maxWidth: {
      type: "select" as const,
      options: [
        { label: "Narrow", value: "narrow" },
        { label: "Standard", value: "standard" },
        { label: "Wide", value: "wide" },
        { label: "Full", value: "full" },
      ],
    },
    align: {
      type: "radio" as const,
      options: [
        { label: "Left", value: "left" },
        { label: "Center", value: "center" },
      ],
    },
    radius: {
      type: "select" as const,
      options: [
        { label: "None", value: "none" },
        { label: "Soft", value: "soft" },
        { label: "Round", value: "round" },
      ],
    },
  },
  defaultProps: {
    content: [],
    tone: "light",
    pad: "regular",
    maxWidth: "standard",
    align: "left",
    radius: "soft",
  },
  render: ContainerRender as unknown as ComponentConfig<ContainerProps>["render"],
};

export const meta = defineMeta({
  title: 'Container',
  description: 'Constrained-width wrapper slot with tone, padding, radius, and max-width controls; use to scope and style groups of nested blocks.',
  categories: ["layout"],
  published: true,
});

.p1-container {
  padding-block: var(--p1-space-md);
  padding-inline: var(--p1-space-lg);
}

.p1-container__outer {
  margin-inline: auto;
  max-inline-size: var(--p1-container-wide);
}

.p1-container__box[data-tone="light"] { background-color: var(--p1-surface-subtle); }
.p1-container__box[data-tone="white"] {
  background-color: var(--p1-surface-default);
  border: 1px solid var(--p1-border);
}

.p1-container__box[data-pad="compact"]  { padding: var(--p1-space-lg); }
.p1-container__box[data-pad="regular"]  { padding: var(--p1-space-xl); }
.p1-container__box[data-pad="spacious"] { padding: var(--p1-space-xl); }
@media (width >= 48rem) {
  .p1-container__box[data-pad="spacious"] { padding: var(--p1-space-3xl); }
}

.p1-container__box[data-radius="soft"]  { border-radius: var(--p1-radius-card); }
.p1-container__box[data-radius="round"] { border-radius: var(--p1-radius-xl); }

.p1-container__inner[data-maxwidth="narrow"]   { max-inline-size: var(--p1-container-narrow); }
.p1-container__inner[data-maxwidth="standard"] { max-inline-size: var(--p1-container-default); }
.p1-container__inner[data-maxwidth="wide"]     { max-inline-size: var(--p1-container-wide); }

.p1-container__inner[data-align="center"] { margin-inline: auto; }

.p1-container__placeholder {
  border: 1px dashed var(--p1-border);
  border-radius: var(--p1-radius-card);
  color: var(--p1-fg-muted);
  font-size: var(--p1-text-sm);
  padding: var(--p1-space-lg);
  text-align: center;
}

